import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const slayingFistCard='a2-p10-r1c2';
export const slayingFistScenarios=['slaying-fist-ordinary','slaying-fist-owner-ordinary','slaying-fist-low','slaying-fist-dedicated','slaying-fist-far','slaying-fist-same-faction','slaying-fist-water','slaying-fist-metal','slaying-fist-lower','slaying-fist-maai-one-ordinary','slaying-fist-maai-one-dedicated','slaying-fist-evade-ordinary','slaying-fist-evade-dedicated','slaying-fist-fate','slaying-fist-suppressed','slaying-fist-silenced','slaying-fist-stopped','slaying-fist-wrong-owner','slaying-fist-decline','slaying-fist-noncounter','slaying-fist-black-ordinary','slaying-fist-black-dedicated','slaying-fist-dead-ordinary','slaying-fist-dead-dedicated','slaying-fist-black-maai','slaying-fist-dead-evade','slaying-fist-black-fate','slaying-fist-black-decline','slaying-fist-white-prohibited','slaying-fist-gad-ordinary','slaying-fist-gad-dedicated','slaying-fist-dia-ordinary','slaying-fist-dia-dedicated','slaying-fist-gad-public','slaying-fist-dia-public','slaying-fist-gad-water','slaying-fist-dia-water','slaying-fist-gad-black','slaying-fist-dia-dead','slaying-fist-gad-maai','slaying-fist-dia-evade','slaying-fist-gad-fate','slaying-fist-dia-decline'] as const;
export type SlayingFistScenario=typeof slayingFistScenarios[number];
export function isSlayingFistScenario(name:string):name is SlayingFistScenario{return (slayingFistScenarios as readonly string[]).includes(name);}
export function slayingFistMode(name:SlayingFistScenario){const suffix=name.replace('slaying-fist-',''),named=suffix.startsWith('gad-')||suffix.startsWith('dia-'),victim=suffix.startsWith('gad-')?'不死王ガドューラ':suffix.startsWith('dia-')?'魔聖母ディア':'黒騎士ガーウィン',dedicated=!(suffix.includes('ordinary')||['low','decline','white-prohibited','black-decline','dia-decline'].includes(suffix)),owner=named||dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',black=suffix.startsWith('black-')||suffix.endsWith('-black'),dead=suffix.startsWith('dead-')||suffix.endsWith('-dead'),water=suffix==='water'||suffix.endsWith('-water'),follower=black?'a2-p22-r1c2':dead?'a2-p22-r3c2':water?'a2-p23-r1c1':suffix==='metal'?'a2-p22-r1c1':suffix==='lower'?'a2-p19-r1c3':null,maai=suffix.startsWith('maai')||suffix.endsWith('-maai'),evade=suffix.startsWith('evade')||suffix.endsWith('-evade'),cancel=suffix.endsWith('fate'),decline=suffix.endsWith('decline'),publicTarget=suffix.endsWith('-public'),damage=named&&dedicated?20:10;return {suffix,dedicated,owner,black,dead,water,follower,maai,evade,cancel,decline,named,victim,publicTarget,damage};}
export function makeSlayingFistPhysical(name:SlayingFistScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=slayingFistMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.suffix==='white-prohibited'?'不死王ガドューラ':m.owner?'大神官ジル':'侍大将のシン',m.victim,'小人のランバ','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:p.id===b?11:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?7:m.dedicated?0:8))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,slayingFistCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3'),takeCard(s,d,'a2-p02-r1c1')];if(m.follower)keep.push(takeCard(s,b,m.follower));if(m.black||m.dead)keep.push(takeCard(s,c,'a2-p19-r3c2'));if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.maai)keep.push(takeCard(s,b,'a2-p06-r1c3'),takeCard(s,b,'a2-p06-r2c1'));if(m.evade)keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`SLAYING_FIST_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('SLAYING_FIST_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('SLAYING_FIST_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('SLAYING_FIST_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if((m.black||m.dead)&&id===c)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p19-r3c2'});if(m.follower&&id===b)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:m.follower});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('SLAYING_FIST_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}if(m.publicTarget){act(b,{type:'REVEAL_CHARACTER'});settle();}return s;
}
